// Helper lambda for Simpson's rule computation on [a, b]
auto simpson_rule = [&f](double a, double b) {
    double c = (a + b) / 2.0;
    double h = (b - a) / 6.0;
    return h * (f(a) + 4.0 * f(c) + f(b));
};

// Recursive adaptive Simpson's rule
auto adaptive_helper = [&](double a, double b, double precision, auto&& self) -> double {
    double c = (a + b) / 2.0;
    double integral_full = simpson_rule(a, b);
    double integral_half1 = simpson_rule(a, c);
    double integral_half2 = simpson_rule(c, b);
    double integral_combined = integral_half1 + integral_half2;
    double error = std::abs(integral_full - integral_combined) / 15.0; // Factor of 15 for Simpson error estimation

    if (error <= 15.0 * precision || (b - a) < std::numeric_limits<double>::epsilon()) {
        return integral_combined + (integral_combined - integral_full) / 15.0; // Correct using error estimate
    } else {
        return self(a, c, precision / 2.0, self) + self(c, b, precision / 2.0, self);
    }
};

return adaptive_helper(a, b, precision, adaptive_helper);

